// Copyright 2015-2021 Crytek GmbH / Crytek Group. All rights reserved.#pragma once#include "Common/GraphicsPipelineStage.h"#include "Common/FullscreenPass.h"class CBloomStage : public CGraphicsPipelineStage{public:	static const EGraphicsPipelineStage StageID = eStage_Bloom;	//! Ray count ceiling for the diffraction streaks, mirrored by CHDRStreaks::s_nMaxDirections.	static const int kMaxStreakDirections = 12; //!< Line passes; each paints two opposed spikes (24 max).	//! Stretch iterations per ray. Each one widens the tap stride by the tap count, so two	//! iterations of 8 taps already reach 63 tap distances from the source.	static const int kStreakIterations = 2;	//! Stretch iterations for the anamorphic horizontal flare. One more than the blade streaks:	//! 8^3 tap distances span the whole frame width, which is what makes the line read as a	//! single stroke across the frame instead of a stubby spike.	static const int kAnamorphicIterations = 3;	CBloomStage(CGraphicsPipeline& graphicsPipeline)		: CGraphicsPipelineStage(graphicsPipeline)		, m_pass1H(&graphicsPipeline)		, m_pass1V(&graphicsPipeline)		, m_pass2H(&graphicsPipeline)		, m_pass2V(&graphicsPipeline)		, m_passStreakThreshold(&graphicsPipeline)		, m_passAnamorphicThreshold(&graphicsPipeline)	{		for (int direction = 0; direction < kMaxStreakDirections; ++direction)		{			for (int iteration = 0; iteration < kStreakIterations; ++iteration)				m_passStreakStretch[direction][iteration].SetGraphicsPipeline(&graphicsPipeline);		}		for (int iteration = 0; iteration < kAnamorphicIterations; ++iteration)			m_passAnamorphicStretch[iteration].SetGraphicsPipeline(&graphicsPipeline);	}	bool IsStageActive(EShaderRenderingFlags flags) const final	{		return CRenderer::CV_r_HDRBloom && CRenderer::CV_r_PostProcess;	}	void Execute();private:	void ExecuteStreaks();	CFullscreenPass m_pass1H;	CFullscreenPass m_pass1V;	CFullscreenPass m_pass2H;	CFullscreenPass m_pass2V;	CFullscreenPass m_passStreakThreshold;	CFullscreenPass m_passStreakStretch[kMaxStreakDirections][kStreakIterations];	CFullscreenPass m_passAnamorphicThreshold;	CFullscreenPass m_passAnamorphicStretch[kAnamorphicIterations];};